function GamePlay:Reset()
    for k, v in pairs(matchData) do
        local match = v;
        match.winTimes = 0;
    end
    this.turnNumber = 0;
    this.winnerID = 0;
    for k, v in pairs(actors) do
        local actor = v;
        actor:Reset();
    end
end

